fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x1c2838);
    host::display::fill_rect(56, 40, 8, h - 120, 0x806040);
    host::display::fill_rect(48, 36, 24, 8, 0x605040);
    let gust: i32 = 160 + tab[(t / 6) & 31] * 90 / 127;
    let mut j: i32 = 0;
    while j < 14 {
        let amp: i32 = j * gust / 52;
        let s: i32 = tab[(t * 3 - j * 5) & 31];
        let off: i32 = s * amp / 127;
        let c: i32 = if s > 0 { 0xe03838 } else { 0xb02020 };
        host::display::fill_rect(64 + j * 14, 90 + off, 14, 100, c);
        j = j + 1;
    }
    host::display::fill_rect(20, h - 40, gust, 8, 0x608090);
    host::display::draw_string(20, h - 60, "GUST", 0x808080, 1);
    host::display::present();
}
